mapper.select:
select request_id, user_id, user_name, reason, status, handle_by, handle_time, handle_remark, new_password, create_time
from sys_password_reset_request
where request_id = #{requestId}

mapper.update:
update sys_password_reset_request
status = #{status}, handle_by = #{handleBy}, handle_time = #{handleTime}, handle_remark = #{handleRemark},
where request_id = #{requestId}
